import { useParams } from 'react-router-dom';

import { Breadcrumbs } from 'components';
import { StyledGridContainer } from 'shared/Styles';

import { CardsContainer, Empty, TrainingCard } from '../../components';
import { pillarStyles } from '../../constants';
import { Pillar, TrainingHubData } from '../../domain';
import { useTrainingData } from '../../hooks';
import {
  StyledTrainingHubHome,
  StyledTrainingHubWrapper,
} from '../Home/Home.styles';
import {
  StyledHighlightedTraining,
  StyledMaterialList,
  StyledPillarContainer,
  StyledPillarDetails,
  StyledPillarDetailsText,
  StyledTotalTrainings,
  StyledTrainingMaterialsTitle,
} from './Pillar.styles';

export const TrainingHubPillar = () => {
  const { trainingData } = useTrainingData();
  const params = useParams();

  const pillarName = params.pillar as string;
  const pillar: Pillar = trainingData[pillarName as keyof TrainingHubData];

  const pageList = [
    {
      pageName: 'Training Hub',
      href: '/training-hub',
    },
    {
      pageName: pillar.name,
      href: `/training-hub/${pillar.name}`,
    },
  ];

  return (
    <StyledGridContainer>
      <StyledTrainingHubWrapper>
        <StyledTrainingHubHome>
          <Breadcrumbs pageList={pageList} showIcon={true} />
        </StyledTrainingHubHome>
        <CardsContainer
          icon={pillarStyles[pillarName].icon}
          variant={pillarName}
          title={pillar.name}
          titleSize="xl"
          style={{ marginTop: '40px' }}
        >
          <StyledPillarContainer>
            <StyledPillarDetails>
              <StyledPillarDetailsText titleSize="xl">
                <div
                  dangerouslySetInnerHTML={{
                    __html: pillar.description as string,
                  }}
                />
              </StyledPillarDetailsText>
              <StyledPillarDetailsText
                titleSize="lg"
                hideIf={!pillar.trainings.length}
              >
                <StyledTotalTrainings>
                  {pillar.trainings.length}
                </StyledTotalTrainings>{' '}
                {pillar.trainings.length > 1 ? 'trainings' : 'training'}
              </StyledPillarDetailsText>
            </StyledPillarDetails>
            <StyledHighlightedTraining>
              {pillar.trainings.slice(0, 2).map((training) => (
                <TrainingCard
                  key={training.id}
                  training={training}
                  pillarId={pillar.id}
                />
              ))}
            </StyledHighlightedTraining>
          </StyledPillarContainer>
        </CardsContainer>
        {!pillar.trainings.length ? (
          <Empty
            type="coming-soon"
            title="Coming soon!"
            description="Training for this pillar will soon be created and added!"
          />
        ) : (
          <>
            <StyledTrainingMaterialsTitle>
              Training Materials
            </StyledTrainingMaterialsTitle>
            <StyledMaterialList>
              {pillar.trainings.map((training) => (
                <TrainingCard
                  key={training.id}
                  training={training}
                  pillarId={pillar.id}
                />
              ))}
            </StyledMaterialList>
          </>
        )}
      </StyledTrainingHubWrapper>
    </StyledGridContainer>
  );
};
